SELECT id, trace_id, tenant_id, owner_user_id, session_id, agent_id, query_text, rewrite_text,
       retrieval_topk, source_docs, answer_score, hallucination_score, create_time
FROM rag_trace
WHERE trace_id = #{traceId}
  AND tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
LIMIT 1

SELECT id, trace_id, tenant_id, owner_user_id, session_id, agent_id, query_text, rewrite_text,
       retrieval_topk, source_docs, answer_score, hallucination_score, create_time
FROM rag_trace
WHERE session_id = #{sessionId}
  AND tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
ORDER BY create_time ASC
